\label{lem-Dm-rep} 
The following are all the irreducible representations of $D_m$,
\begin{gather*}
    \{\mathds{1}, \varepsilon\} \cup \{\rho_1, \dots, \rho_{\frac{m-1}{2}}\}, \quad \text{if $m$ is odd}; \\
    \{\mathds{1}, \varepsilon, \varepsilon_r, \varepsilon_t\} \cup \{\rho_1, \dots, \rho_{\frac{m}{2}-1}\}, \quad \text{if $m$ is even}.
\end{gather*}
These representations are non-isomorphic to each other.

\label{lem-2.4} \leavevmode
  \begin{enumerate}
    \item \label{lem-2.4-1} The $+1$-eigenspace of either $r$ or $t$ in the representation space $V_{r,t}$ of $\rho_k$ $(1 \le k \le \frac{m}{2})$ is one dimensional.
    \item \label{lem-2.4-2} No nonzero vector in $V_{r,t}$ can be fixed by $r$ and $t$ simultaneously.
  \end{enumerate}

\label{lem-2.6}
If $d>1$ is a common divisor of $k$ and $m$ $(1 \le k \le \frac{m}{2})$, then $\rho_k$ factors through $D_{\frac{m}{d}}$ as follows:
\begin{equation*}
    \xymatrix{D_m \ar[rr]^{\rho_k} \ar@{->>}[rd]& & GL(V_{r,t}) \\
             & D_{\frac{m}{d}} \ar[ur]_{\rho_{\frac{k}{d}}} &}
\end{equation*}
Here $D_m \twoheadrightarrow D_{\frac{m}{d}}$ is the natural homomorphism.

\label{lem-2.7}
If $k < \frac{m}{2}$, then there exists a unique up to a $\mathbb{C}^\times$-scalar nonzero bilinear form $(- |-)$ on $V_{r,t}$ which is invariant under the action $\rho_k$ of $D_m$:
\begin{equation}  \label{eq-Bform}
    (\beta_r|\beta_r) = (\beta_t| \beta_t) = 1, \quad (\beta_r|\beta_t) = (\beta_t| \beta_r) = -\cos \frac{k \uppi}{m}.
\end{equation}
In particular, $(- |-)$ is symmetric.

Under the ordered basis $(\beta_r, \beta_t)$ of $V_{r,t}$, we denote the representing matrix of $(- | -)$ by $B \in M_2(\mathbb{C})$, and the matrices of $r$ and $t$ by $R$ and $T$ respectively,
  \begin{equation*}
    R = \begin{pmatrix}
          -1 & 2\cos \frac{k \uppi}{m} \\
          0 & 1
        \end{pmatrix}, \quad
    T = \begin{pmatrix}
          1 & 0 \\
          2 \cos \frac{k \uppi}{m} & -1
        \end{pmatrix}.
  \end{equation*}
  Note that $k < \frac{m}{2}$ implies $\cos \frac{k \uppi}{m} \ne 0$.
  The condition that $(-|-)$ is $D_m$-invariant is equivalent to the equations
  \begin{equation}   \label{eq-bil-mat}
    R^\mathrm{T} B R = B, \quad T^\mathrm{T} B T = B.
  \end{equation}
  Here the superscript $(-)^\mathrm{T}$ denotes the transpose of a matrix.
  By direct computations, Equation \eqref{eq-bil-mat} suggests that $B$ must be a $\mathbb{C}^\times$-multiple of
  \begin{equation*}
    \begin{pmatrix}
      1 & -\cos \frac{k \uppi}{m} \\
      -\cos \frac{k \uppi}{m} & 1
    \end{pmatrix}.
  \end{equation*}
  The lemma is proved.

\label{lem-fdih-sesqui}
  Suppose $k < \frac{m}{2}$, and $[- | -]$ is a nonzero sesquilinear form on $V_{r,t}$ which is $D_m$-invariant under the action $\rho_k$.
  Then there exists $c \in \mathbb{C}^\times$ such that
  \begin{equation*}
        [\beta_r|\beta_r] = [\beta_t| \beta_t] = c, \quad [\beta_r|\beta_t] = [\beta_t| \beta_r] = -c \cos \frac{k \uppi}{m}.
  \end{equation*}
  Furthermore, $[- | -]$ is Hermitian if and only if $c \in \mathbb{R}^\times$.

\label{lem-infdih-ind-rep}
  All the indecomposable representations of $D_\infty$ of dimension $1$ or $2$  are given by:
  \begin{equation}   \label{eq-list-infdih}
    \{\mathds{1}, \varepsilon, \varepsilon_r, \varepsilon_t\} \cup \{ \varrho_r^t, \varrho_t^r, \varrho_{\varepsilon}^{\mathds{1}}\} \cup \{\varrho_z \mid z \in \mathbb{C}^\times\}.
  \end{equation}
  These representations are non-isomorphic to each other.

\label{lem-2.11}
  Suppose $\varrho \in \{\varrho_r^t, \varrho_t^r\} \cup \{\varrho_z \mid z \in \mathbb{C}^\times\}$.
  \begin{enumerate}
    \item \label{lem-infdih-schur} An endomorphism of $\varrho$ must be a scalar.
    \item \label{2.4.4} There is a unique up to a $\mathbb{C}^\times$-scalar $D_\infty$-invariant nonzero bilinear form $(-|-)$ on the representation space of $\varrho$. The representing matrix of $(-|-)$ (with respect to the ordered basis $(\beta_r, \beta_t)$) is
         \begin{gather*}
           \begin{pmatrix}
            1 & -\frac{u}{2} \\
            -\frac{u}{2} & 1
           \end{pmatrix}, \text{ if } \varrho = \varrho_z, z \neq 0; \\
           \begin{pmatrix}
            1 & 0 \\
            0 & 0
           \end{pmatrix}, \text{ if } \varrho = \varrho_t^r; \\
           \begin{pmatrix}
            0 & 0 \\
            0 & 1
          \end{pmatrix}, \text{ if } \varrho = \varrho_r^t.
         \end{gather*}
  \end{enumerate}

\label{lem-refl}
  Let $V$ be a vector space and $s : V \to V$ be a reflection with a reflection vector $\alpha_s$.
  Then for any $v \in V$ we have $v - s\cdot v \in \mathbb{C} \alpha_s$.

\label{lem4.2}
  Let $V = \bigoplus_{s \in S} \mathbb{C} \alpha_s$ be a generalized geometric representation of $W$, where $\alpha_s$ is a reflection vector of $s$.
  \begin{enumerate}
    \item \label{4.2-1} Suppose $r, t \in S$, $r \ne t$. The vectors $\alpha_r, \alpha_t$ span in $V$ a subrepresentation of the dihedral subgroup $\langle r,t \rangle$.
    \item \label{4.2-2} This representation of $\langle r,t \rangle$, say $\phi_{rt}: \langle r,t \rangle \to GL(\mathbb{C} \langle \alpha_r, \alpha_t \rangle)$,  is isomorphic to $\rho_{k_{rt}}$ for some $1 \leq k_{rt} \leq \frac{m_{rt}}{2}$.
  \end{enumerate}

If a set of numbers $(k_{rt}, a_r^t)_{r,t \in S, r \neq t}$ satisfies the following:
  \begin{equation*}
    k_{rt} \in \mathbb{N}, \quad 1 \leq k_{rt} = k_{tr} \leq \frac{m_{rt}}{2}, \quad a_r^t \in \mathbb{C}^\times, \quad \forall r,t \in S, r \ne t,
  \end{equation*}
  then $(k_{rt}, a_r^t)_{r,t \in S, r \neq t}$ is called a \emph{GGR-datum} of $W$ (``GGR'' stands for ``generalized geometric representation'').

\leavevmode
  \begin{enumerate}
    \item Forgetting the labels on the edges, the graph $\widetilde{G}$ is a subgraph of the Coxeter graph $G$ of $W$ with the same vertex set $S$.
        An edge $\{r,t\}$ in $G$ is an edge in $\widetilde{G}$ if and only if $k_{rt} \ne \frac{m_{rt}}{2}$.
    \item It may happen that $G$ is connected but $\widetilde{G}$ has several components.
    \item We have a canonical homomorphism $W \twoheadrightarrow \widetilde{W}$.
    \item Let $\rho: W \to GL(V)$ be the generalized geometric representation of $W$ defined by the datum
        $(k_{rt}, a_r^t)_{r,t \in S, r \neq t}$.
        By Lemma \ref{lem-2.6}, the representation $\rho$ naturally factors through $\widetilde{W}$ as follows,
        \begin{equation*}
           \xymatrix{W \ar[rr]^{\rho} \ar@{->>}[rd]& & GL(V) \\
             & \widetilde{W} \ar[ur]_{\widetilde{\rho}} &}
        \end{equation*}
        Moreover, $\widetilde{\rho}: \widetilde{W} \to GL(V)$ is a generalized geometric representation of $\widetilde{W}$ defined by the GGR-datum $(\widetilde{k}_{rt}, a_r^t)_{r,t \in S, r \neq t}$ of $\widetilde{W}$, where $\widetilde{k}_{rt} := \frac{k_{rt}}{d_{rt}}$.
  \end{enumerate}

\label{eg-chi}
  Suppose the Coxeter graph $G$ of the Coxeter group $(W,S)$ is as follows,
  \begin{equation*}
  \begin{tikzpicture}
    \node [circle, draw, inner sep=2pt, label=90:$s$] (s) at (0,0.7) {};
    \node [circle, draw, inner sep=2pt, label=270:$t$] (t) at (0,-0.7) {};
    \node [circle, draw, inner sep=2pt, label=right:$r$] (r) at (2,0) {};
    \node [circle, draw, inner sep=2pt, label=left:$u$] (u) at (-2,0) {};
    \draw (s) -- (t) -- (r) -- (s) -- (u) -- (t);
    \node (tr) at (1, -0.6) {$6$};
    \node (sr) at (1,0.6) {$5$};
    \node (tu) at (-1,-0.6) {$4$};
  \end{tikzpicture}
  \end{equation*}
  Let $k_{su} = k_{st} = 1$ and $k_{sr} = k_{tr} = k_{tu} = 2$.
  Then the associated graph $\widetilde{G}$ is as follows,
  \begin{equation*}
  \begin{tikzpicture}
    \node [circle, draw, inner sep=2pt, label=90:$s$] (s) at (0,0.7) {};
    \node [circle, draw, inner sep=2pt, label=270:$t$] (t) at (0,-0.7) {};
    \node [circle, draw, inner sep=2pt, label=right:$r$] (r) at (2,0) {};
    \node [circle, draw, inner sep=2pt, label=left:$u$] (u) at (-2,0) {};
    \draw (s) -- (t) -- (r) -- (s) -- (u);
    \node (sr) at (1,0.6) {$5$};
  \end{tikzpicture}
  \end{equation*}
  The homology group $H_1(\widetilde{G})$ is isomorphic to $\mathbb{Z}$, generated by the circuit $(s,r,t,s)$.
  Let $a_t^r = x \in \mathbb{C}^\times$ and $a_r^t = a_s^t = a_t^s = a_r^s = a_s^r = 1$.
  Then the associated character $\chi$ takes the value $x$ on the circuit $(s,r,t,s)$.

\label{lem-k=l}
  Suppose $\varphi: V_1 \xrightarrow{\sim} V_2$ is an isomorphism of representations.
  Then $k_{rt} = l_{rt}$ for any $r, t \in S$ with $r \ne t$.

Let $(s_1, s_2, \dots, s_n, s_1)$ be a circuit in $\widetilde{G}$.
We write $\alpha_i := \alpha_{s_i}$ and $a_i^j := a_{s_i}^{s_j}$ for convenience, and similar for $m_{ij}, \widetilde{m}_{ij}, k_{ij},$ $\alpha_i^\prime, b_i^j$, etc.

Since $(s_1, s_2)$ is an edge of $\widetilde{G}$, we have $k_{12} \neq \frac{m_{12}}{2}$.
Thus $\mathbb{C} \langle \alpha_1, \alpha_2 \rangle$ and $\mathbb{C} \langle \alpha_1^\prime,  \alpha_2^\prime \rangle$ are irreducible representations of the subgroup $\langle s_1, s_2 \rangle$, both isomorphic to 
\[\rho_{k_{12}}: \langle s_1, s_2 \rangle \to GL(\mathbb{C}\beta_1 \oplus \mathbb{C} \beta_2).\]
We denote the two isomorphisms by $\psi_1, \psi_2$ respectively as follows (not a commutative diagram):
\begin{equation*}
  \xymatrix{ & \mathbb{C} \langle \beta_1, \beta_2 \rangle \ar[rd]_\sim^{\psi_2} \ar[ld]^\sim_{\psi_1} & \\
  \mathbb{C} \langle \alpha_1, \alpha_2 \rangle \ar[rr]^{\varphi|_{\mathbb{C} \langle \alpha_1, \alpha_2 \rangle}}_\sim & & \mathbb{C} \langle \alpha_1^\prime,  \alpha_2^\prime \rangle}
\end{equation*}
As in Subsection \ref{subsec-struIR}, the two maps $\psi_1, \psi_2$ can be chosen so that
\begin{equation}   \label{eq-chi1=2-3}
  \begin{aligned}
     \psi_1(\beta_1) & = a_1^2 \alpha_1, \quad & \psi_1(\beta_2) & = a_2^1 \alpha_2, \\
     \psi_2(\beta_1) & =  b_1^2 \alpha^\prime_1, & \psi_2(\beta_2) & = b_2^1 \alpha^\prime_2.
  \end{aligned}
\end{equation}

Since $\alpha_1, \alpha_1^\prime$ are reflection vectors of $s_1$ in $V_1, V_2$ respectively, there exists  some $x \in \mathbb{C}^\times$ such that $\varphi(\alpha_1) = x \alpha_1^\prime$.
Then
\begin{equation}   \label{eq-chi1=2-4}
  \psi_2^{-1} \varphi \psi_1 (\beta_1) = \psi_2^{-1} \varphi (a_1^2 \alpha_1) = \psi_2^{-1} (x a_1^2 \alpha_1^\prime) = x \frac{a_1^2}{b_1^2} \beta_1.
\end{equation}
Note that $\psi_2^{-1} \varphi \psi_1$ is an automorphism of $\rho_{k_{12}}$.
By Schur's Lemma \ref{lem-schur}, Equation \eqref{eq-chi1=2-4} implies
\begin{equation}   \label{eq-chi1=2-5}
  \psi_2^{-1} \varphi \psi_1 (\beta_2) = x \frac{a_1^2}{b_1^2} \beta_2.
\end{equation}
Therefore, by Equations \eqref{eq-chi1=2-3} and \eqref{eq-chi1=2-5}, we have
\begin{equation*}
  \varphi(\alpha_2) = \frac{1}{a_2^1} \varphi \psi_1(\beta_2) = \frac{1}{a_2^1} \cdot x \frac{a_1^2}{b_1^2} \psi_2(\beta_2) = x \frac{a_1^2 b_2^1}{a_2^1 b_1^2} \alpha_2^\prime.
\end{equation*}

In simple terms, for the edge $(s_1, s_2)$ we have shown that
\begin{equation*}
  \varphi(\alpha_1) = x \alpha_1^\prime \xLongrightarrow{\text{ Schur's lemma }} \varphi(\alpha_2) = x \frac{a_1^2 b_2^1}{a_2^1 b_1^2} \alpha_2^\prime.
\end{equation*}
Do this argument for the edges $(s_2, s_3), \dots, (s_{n-1}, s_n), (s_n, s_1)$ recursively, and finally we get
\begin{equation}   \label{eq-chi1=2-1}
    \varphi(\alpha_1) = x \frac{a_1^2 a_2^3 \cdots a_{n-1}^n a_n^1 b_2^1 b_3^2 \cdots b_n^{n-1} b_1^n}{a_2^1 a_3^2 \cdots a_n^{n-1} a_1^n b_1^2 b_2^3 \cdots b_{n-1}^n b_n^1} \alpha_1^\prime.
\end{equation}
Compare Equation \eqref{eq-chi1=2-1} with $\varphi(\alpha_1) = x \alpha_1^\prime$, then we have
\begin{equation}   \label{eq-chi1=2-2}
    \frac{a_2^1 a_3^2 \cdots a_n^{n-1} a_1^n}{a_1^2 a_2^3 \cdots a_{n-1}^n a_n^1} = \frac{b_2^1 b_3^2 \cdots b_n^{n-1} b_1^n}{b_1^2 b_2^3 \cdots b_{n-1}^n b_n^1}.
\end{equation}
The two sides of Equation \eqref{eq-chi1=2-2} are the images of the arbitrarily chosen circuit $(s_1, s_2, \dots, s_n, s_1)$ under $\chi_1$ and $\chi_2$ respectively.
It follows that $\chi_1 = \chi_2$.

Choose a spanning forest $\widetilde{G}_0 = (S, E_0)$ of the associated graph $\widetilde{G} = (S,E)$.
For any $\mathfrak{e} \in E \setminus E_0$, choose an orientation of $\mathfrak{e}$.
Let $c_\mathfrak{e}$ be defined as in Subsection \ref{subsec-graph}.
Then by Lemma \ref{lem-2.12}, we have
\begin{equation*}
    H_1(\widetilde{G}) = \bigoplus_{\mathfrak{e} \in E \setminus E_0} \mathbb{Z} c_\mathfrak{e}.
\end{equation*}
Therefore, a character $\chi$ of $H_1(\widetilde{G})$ is determined by the values $\{\chi(c_\mathfrak{e}) \mid \mathfrak{e} \in E \setminus E_0 \}$.

Let $\chi$ be an arbitrary character of $H_1(\widetilde{G})$.
For any  $r,t \in S$ with $r \ne t$, let
\begin{equation*}
    a_r^t := \begin{cases}
              \chi(c_{(t,r)}), & \mbox{if } \{t,r\} \in E \setminus E_0, \mbox{ and is oriented as } (t,r); \\
              1, & \mbox{otherwise.} \\

            \end{cases}
\end{equation*}
Then, $\chi$ is the character associated with the datum $(k_{rt}, a_r^t)_{r,t \in S, r \ne t}$ (for an illustrative example, see Example \ref{eg-chi}).
Let $V$ be the generalized geometric representation defined by the datum $(k_{rt}, a_r^t)_{r,t \in S, r \ne t}$, then  $\Theta(V) = \chi$.

\label{rmk-322} \leavevmode 
  \begin{enumerate}
    \item \label{rmk-322-1} In fact, by Schur's lemma, Equation \eqref{eq-lem-inj-3} is the only feasible way to define $\varphi(\alpha_s)$ once $\varphi(\alpha_r) = \alpha_r^\prime$ is defined for the base point $r$.
    \item Lemma \ref{lem-inj} is essentially a converse of Lemma \ref{lem-chi1=2}.
  \end{enumerate}

\label{thm-IR}
  The isomorphism classes of generalized geometric representations of $W$ one-to-one correspond to the set of data
  \begin{equation*}
    \left\{ \bigl((k_{rt})_{r, t \in S, r \ne t}, \chi\bigr) \text{ } \middle\vert 
    \begin{gathered}
      \text{ $k_{rt} \in \mathbb{N}$, $1 \leq k_{rt} = k_{tr} \leq \frac{m_{rt}}{2}$, $\forall r, t \in S$, $r \ne t$;} \\
      \text{$\chi$ is a character of  $H_1(\widetilde{G}$), where} \\
      \text{$\widetilde{G}$ is the associated graph of $(k_{rt})_{r,t \in S, r \ne t}$}
    \end{gathered} \right\}.
  \end{equation*}

\label{eg-affine-A}
  The Coxeter group $(W,S)$ of type $\widetilde{\mathsf{A}}_n$ is defined by $$\langle s_0, s_1, \dots, s_n \mid s_i^2 = (s_i s_{i+1})^3 = e, \forall i = 0, \dots, n \rangle$$ (regard $n+1$ as $0$).
  Its Coxeter graph $G$ is as follows,
  \begin{equation*}
  \begin{tikzpicture}
    \node [circle, draw, inner sep=2pt, label=below:$s_1$] (s1) at (-2,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_2$] (s2) at (-1,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_{n-1}$] (sn-1) at (1,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_n$] (sn) at (2,0) {};
    \node [circle, draw, inner sep=2pt, label=left:$s_0$] (s0) at (0,1) {};
    \draw (sn-1) -- (sn) -- (s0) -- (s1) -- (s2);
    \draw (s2) -- (-0.5,0);
    \draw (sn-1) -- (0.5,0);
    \node (d) at (0,0) {$\dots$};
  \end{tikzpicture}
  \end{equation*}
  We use the notation $(k_{ij}, a_i^j)_{0\le i \ne j \le n}$ to indicate the GGR-datum $(k_{s_is_j}, a_{s_i}^{s_j})_{i \ne j}$, as we did in the proof of Lemma \ref{lem-chi1=2}.
  The condition $1 \leq k_{ij} \leq \frac{m_{ij}}{2}$ forces $k_{ij} = 1$.
  Thus the associated graph $\widetilde{G}$ is the same as $G$.
  The homology group $H_1 (G)$ is isomorphic to $\mathbb{Z}$ generated by the circuit $c = (s_0, s_1, \dots, s_n, s_0)$.
  Giving a character $\chi$ of $H_1 (G)$ is equivalent to giving a number $x \in \mathbb{C}^\times$ and assigning $\chi(c) = x$.
  Such character $\chi$ can be realized by choosing $a_0^n = x$ and $a_n^0 = a_0^1 = a_1^0 =  \dots = 1$.
  Therefore, all generalized geometric representations of $W$ are parameterized by $\mathbb{C}^\times$.

Assume $(W,S)$ is irreducible.
 \begin{enumerate}
   \item The geometric representation $V_{\text{geom}}$ is irreducible if and only if the bilinear form $(-|-)$ defined in Equation \eqref{eq-B-Vg} is non-degenerate.
   \item If $V_{\text{geom}}$ is reducible, then it has a maximal subrepresentation $V_0$ with trivial $W$-action, and the quotient $V_{\text{geom}} / V_0$ is irreducible.
 \end{enumerate}

\label{lem-decomp-into-comp}
  Notations as above.
  \begin{enumerate}
    \item $\widetilde{W} = \prod_{i \in I} \widetilde{W}_i$.
    \item The representation $V$ is decomposed into $V = \bigoplus_{i \in I} V_i$, where 
        \[V_i = \bigoplus_{s \in S_i} \mathbb{C} \alpha_s\]
        is a subrepresentation of $W$.
    \item For $j \neq i$, $W_j$ acts trivially on $V_i$.
    \item Each $V_i$ is a generalized geometric representation of the Coxeter group $(W_i, S_i)$, defined by the datum $(k_{rt}, a_r^t)_{r,t \in S_i, r\neq t}$, and factors through $\widetilde{W}_i$.
  \end{enumerate}

\label{prop-reducibility}
Notations as above.
Suppose $\widetilde{G}$ is connected, and $U \subsetneq V$ is a subrepresentation of $W$.
\begin{enumerate}
  \item \label{prop-red-1} The action of $W$ on $U$ is trivial.
  \item \label{prop-red-2} If $V$ is reducible, then $V$ has a maximal subrepresentation $V_0$ with trivial $W$-action, and the quotient $V/V_0$ is irreducible.
  \item \label{prop-red-3} The representation $V$ is indecomposable.
\end{enumerate}

\label{thm-reducibility}
  Let $V$ be a generalized geometric representation of $W$ defined by a GGR-datum, say,  $(k_{rt}, a_r^t)_{r,t \in S, r\ne t}$. 
  Suppose the associated graph $\widetilde{G}$ is connected.
  \begin{enumerate}
    \item \label{6.3-1} The representation $V$ is irreducible if and only if the matrix $A$ defined in Equation \eqref{matrixA} is invertible.
    \item \label{6.3-2} If $V$ is reducible, and $V_0$ is the maximal subrepresentation, then the quotient $V/V_0$ is irreducible of dimension $\operatorname{rank}(A)$.
  \end{enumerate}

In Example \ref{eg-affine-A}, if we choose $a_0^n = x$ and $a_n^0 = a_0^1 = a_1^0 =  \dots = 1$, then the associated character $\chi$ satisfies $\chi(c) = x$.
  The square matrix $A$ (of size $n + 1$, defined in Equation \eqref{matrixA}) is
  \begin{equation*}
    A = \begin{pmatrix}
        1 & - \frac{1}{2} & 0 & \dots & 0 & - \frac{x}{2} \\
        - \frac{1}{2} & 1 & - \frac{1}{2} &  & & 0 \\
        0 & - \frac{1}{2} & \ddots & \ddots &  & \vdots \\
        \vdots &  & \ddots & \ddots & - \frac{1}{2} & 0 \\
        0 & &  & - \frac{1}{2} & 1 & - \frac{1}{2} \\
        - \frac{1}{2x} & 0 & \dots & 0 & - \frac{1}{2} & 1
      \end{pmatrix}
  \end{equation*}
  One may use induction on $n$ to compute the determinant of $A$,
  \begin{equation*}
    \det A = \frac{2 - x - x^{-1}}{2^{n+1}}.
  \end{equation*}
  Then, by Theorem \ref{thm-reducibility}, this generalized geometric representation is irreducible if and only if $x \neq 1$.
  If $x = 1$, then this representation is the geometric representation $V_{\text{geom}}$ of $\widetilde{\mathsf{A}}_n$.

\label{cor-reducibility}
  Suppose $V$ is a generalized geometric representation of $W$. Let
  \begin{equation*}
    V_0 := \{v \in V \mid w \cdot v = v, \forall w \in W\}
  \end{equation*}
  be the maximal subrepresentation with trivial $W$-action.
  Then $V/V_0$ is semisimple and $\dim V/V_0 = \operatorname{rank}(A)$.
  In particular, $V$ is semisimple if and only if $A$ is invertible.

\label{def-R}
  Let $V$ be a reflection representation of $W$.
  We call $V$ an R-representation of $W$ if 
  \begin{enumerate}
    \item $V$ is spanned by reflection vectors $\{\alpha_s\mid s\in S\}$;
    \item for any pair $r, t \in S$ $(r \ne t)$ such that $m_{rt} < \infty$, the vectors $\alpha_r, \alpha_t$ are linearly independent.
  \end{enumerate}

Suppose $W$ is of type $\widetilde{\mathsf{A}}_2 \times \widetilde{\mathsf{A}}_2$, i.e., the Coxeter graph of $W$ is as follows,
\begin{equation*}
    \begin{tikzpicture}
      \node [circle, draw, inner sep=2pt, label=left:$s_1$] (s1) at (-1.5,1) {};
      \node [circle, draw, inner sep=2pt, label=below:$s_2$] (s2) at (-2.5,0) {};
      \node [circle, draw, inner sep=2pt, label=below:$s_3$] (s3) at (-0.5,0) {};
      \draw (s3) -- (s1) -- (s2) -- (s3);
      \node [circle, draw, inner sep=2pt, label=left:$s_4$] (s4) at (1.5,1) {};
      \node [circle, draw, inner sep=2pt, label=below:$s_5$] (s5) at (0.5,0) {};
