The  geometric representation $V_{\text{geom}}$  is a direct sum of two copies of the geometric representation of $\widetilde{\mathsf{A}}_2$.
Let $v_1 := \alpha_1 + \alpha_2 + \alpha_3$, $v_2 := \alpha_4 + \alpha_5 + \alpha_6$.
Then $V_0 := \mathbb{C}\langle v_1, v_2 \rangle$ is the maximal subrepresentation in $V_{\text{geom}}$ with trivial $W$-action.
The two quotients $V_{\text{geom}}/\mathbb{C} v_1$ and $V_{\text{geom}}/\mathbb{C} v_2$ are clearly non-isomorphic.
However, let $V_1 := V_{\text{geom}}/\mathbb{C} (v_1 + v_2)$, $V_2 := V_{\text{geom}}/\mathbb{C} (v_1 + 2v_2)$, then the map $\alpha_i \mapsto \alpha_i, i = 1,2,3$, $\alpha_j \mapsto 2 \alpha_j, j = 4,5,6$ defines an isomorphism from $V_1$ to $V_2$.

\label{prop-bil}
  Let $V = \bigoplus_{s \in S} \mathbb{C} \alpha_s$ be a generalized geometric representation of $W$ defined by a GGR-datum $(k_{rt}, a_r^t)_{r,t \in S, r \ne t}$, and $\chi$ be the associated character. Assume the associated graph $\widetilde{G}$ is connected.
  \begin{enumerate}
    \item \label{prop-bil-1} There is a nonzero $W$-invariant bilinear form on $V$ if and only if \[\chi (H_1 (\widetilde{G})) \subseteq \{\pm 1\}.\]
    \item \label{prop-bil-2} There is a nonzero $W$-invariant sesquilinear form on $V$ if and only if \[\chi (H_1 (\widetilde{G})) \subseteq S^1 := \{z \in \mathbb{C} \mid \lvert z \rvert = 1\}.\]
  \end{enumerate}

Let $V$ be a generalized geometric representation of $W$.
Suppose the associated graph $\widetilde{G}$ is connected and $V$ admits a nonzero $W$-invariant bilinear form $(-|-)$.
  \begin{enumerate}
    \item Such a bilinear form is symmetric and is unique up to a $\mathbb{C}^\times$-scalar.
    \item For any $s \in S$, the action of $s$ on $V$ is an orthogonal reflection with respect to $(-|-)$, i.e.,
        \begin{equation*}
          s \cdot \alpha_t = \alpha_t - \frac{2(\alpha_t|\alpha_s)}{(\alpha_s | \alpha_s)} \alpha_s, \quad \forall t \in S.
        \end{equation*}
  \end{enumerate}

