\label{lem-dual-dih}
  Notations as above.
  \begin{enumerate}
    \item \label{lem-dual-1} For $r,t \in S$ with $r \ne t$, we have $r \cdot \gamma_t = \gamma_t + 2 \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} \gamma_r$.
    \item \label{lem-dual-2} For $r,t \in S$ with $r \ne t$, the vectors $\gamma_r$ and $\gamma_t$ are linearly independent.
  \end{enumerate}

The proof of \eqref{lem-dual-1} is just a direct computation using Equations \eqref{eq6.5}, \eqref{eq6.6} and \eqref{eq-6.5},
  \begin{align}
    r \cdot \gamma_t & = r \cdot \Bigl( \alpha_t^* - \sum_{s \neq t} \frac{a_t^s}{a_s^t} \cos \frac{k_{st} \uppi}{m_{st}} \alpha_s^* \Bigr) \notag \\
    & = \Bigl( \alpha_t^* - \sum_{s \neq r, t} \frac{a_t^s}{a_s^t} \cos \frac{k_{st} \uppi}{m_{st}} \alpha_s^* \Bigr) - \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} (r \cdot \alpha_r^*) \notag \\
    & = \Bigl( \alpha_t^* - \sum_{s \neq r, t} \frac{a_t^s}{a_s^t} \cos \frac{k_{st} \uppi}{m_{st}} \alpha_s^* \Bigr) \notag  - \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} \Bigl( - \alpha_r^* + 2 \sum_{s \neq r}  \frac{a_r^s}{a_s^r} \cos \frac{k_{sr} \uppi}{m_{sr}} \alpha_s^* \Bigr)  \notag \\
    & = \Bigl( \alpha_t^* - \sum_{s \neq  t} \frac{a_t^s}{a_s^t} \cos \frac{k_{st} \uppi}{m_{st}} \alpha_s^* \Bigr) \notag  +
    \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} \Bigl( 2 \alpha_r^* - 2 \sum_{s \neq r}  \frac{a_r^s}{a_s^r} \cos \frac{k_{sr} \uppi}{m_{sr}} \alpha_s^* \Bigr)  \notag \\
    & = \gamma_t + 2 \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} \gamma_r.   \label{eq-lem-dual}
  \end{align}

  Now we prove \eqref{lem-dual-2}.
  We have
  \begin{align*}
    \gamma_r & = \alpha_r^* - \frac{a_r^t}{a_t^r} \cos \frac{k_{rt} \uppi}{m_{rt}} \alpha_t^* - \sum_{s \neq r, t} \frac{a_r^s}{a_s^r} \cos \frac{k_{sr} \uppi}{m_{sr}} \alpha_s^*, \\
    \gamma_t & = \alpha_t^* - \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} \alpha_r^* - \sum_{s \neq r, t} \frac{a_t^s}{a_s^t} \cos \frac{k_{st} \uppi}{m_{st}} \alpha_s^*.
  \end{align*}
  Note that $\{\alpha_s^* \mid s \in S\}$ is a basis of $V^*$.
  If $\gamma_r$ and $\gamma_t$ are proportional, then
  \begin{equation*}
    1 = \left(\frac{a_r^t}{a_t^r} \cos \frac{k_{rt} \uppi}{m_{rt}} \right) \left( \frac{a_t^r}{a_r^t} \cos \frac{k_{rt} \uppi}{m_{rt}} \right) = \cos^2 \frac{k_{rt} \uppi}{m_{rt}}
  \end{equation*}
  which is impossible since $1 \le k_{rt} \le \frac{m_{rt}}{2} < \infty$ (currently we assume that $m_{rt} < \infty$, see assumption \eqref{eq-fin-condition}).

