    \item \label{thm-refl-2} The map $\theta_i \mapsto \rho(s_i)$ defines an R-representation $\overline{\rho}: \overline{W} \to GL(V)$.
    \item \label{thm-refl-3} The reflection representation $(V, \rho)$ of $W$ factors through $(\overline{W}, \overline{S})$ as follows,
        \begin{equation*}
           \xymatrix{W \ar[rr]^{\rho} \ar@{->>}[rd]_{\pi_V}& & GL(V) \\
             & \overline{W} \ar[ur]_{\overline{\rho}} &}
         \end{equation*}
  \end{enumerate}

Let $S = I_1 \sqcup \cdots \sqcup I_k$ be a partition of the set $S$.
  As in \eqref{eq-dij}, for two indices $i,j$ with $1 \le i \ne j \le k$ we set
  \begin{equation*}
    d_{ij} := \gcd \{m_{rt} \mid r \in I_i, t \in I_j, m_{rt} < \infty\}.
  \end{equation*}
  (Recall that we set $\gcd \emptyset = \infty$.)
  The partition is called an \emph{admissible partition} of $S$ 
  if the following two conditions are satisfied:
  \begin{enumerate}
    \item  $d_{ij} > 1$ for any indices $i,j$ with $i \ne j$;
    \item for each index $i$, $I_i$ can not be written as a disjoint union 
      $I_i = J \sqcup J^\prime$ such that $m_{rt} = \infty$ 
      for any $r \in J$ and $t \in J^\prime$.
  \end{enumerate}

The isomorphism classes of reflection representations (spanned by reflection vectors) of $W$ one-to-one correspond to the data 
  $\{(S = I_1 \sqcup \cdots \sqcup I_k, (V, \overline{\rho}))\}$
  where
  \begin{enumerate}
    \item $S = I_1 \sqcup \cdots \sqcup I_k$ is an admissible partition of $S$;
    \item $(V, \overline{\rho})$ is an (isomorphism class of) R-representation of $\overline{W}$, where $\overline{W}$ is a quotient of $W$ defined by the partition as in the last subsection.
  \end{enumerate}

\label{eg-610}
  Let $W$ be the symmetric group $\mathfrak{S}_{n+1}$, with Coxeter graph
  \begin{equation*}
    \begin{tikzpicture}
    \node [circle, draw, inner sep=2pt, label=below:$s_1$] (s0) at (-3,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_2$] (s1) at (-2,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_3$] (s2) at (-1,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_{n-1}$] (sn-1) at (1,0) {};
    \node [circle, draw, inner sep=2pt, label=below:$s_{n}$] (sn) at (2,0) {};
    \draw (sn-1) -- (sn);
    \draw (s0) -- (s1) -- (s2);
    \draw (s2) -- (-0.5,0);
    \draw (sn-1) -- (0.5,0);
    \node (d) at (0,0) {$\dots$};
    \end{tikzpicture}
  \end{equation*}

  If $n = 3$, the partition $S = \{s_1, s_3\} \sqcup \{s_2\}$ is the only admissible partition which is non-trivial and non-discrete.

  Suppose $n \ge 4$, $S = I_1 \sqcup \cdots \sqcup I_k$ is an admissible partition and $s_i, s_j \in I_1$ with $1 \le i < j \le n$.
  If $s \in S$ is a vertex in the Coxeter graph which is adjacent to one of $s_i$ and $s_j$ while non-adjacent to the other (e.g., $s= s_{i-1}$ if $i > 1$, or $s= s_{i+1}$ if $j-i>2$), then $s$ must belong to $I_1$ as well because $m_{ss_i}$ and $m_{ss_j}$ are co-prime.
  In this way one easily deduces that the partition of $S$ must be trivial or discrete.
  In other words, a reflection representation of $\mathfrak{S}_{n+1}$ ($n \ge 4$) is either the sign representation or an R-representation (in fact, the only R-representation of $\mathfrak{S}_{n+1}$ is the geometric representation $V_{\text{geom}}$).
